window.VOL8_TESTS[2]={"id": 2, "module": "listening", "vol": 8, "sections": [{"number": 1, "html": "<p class=\"subheading\"><b>Questions 1–10</b></p><p class=\"instruction\">Complete the form below.</p><p class=\"instruction\">Write <b>NO MORE THAN TWO WORDS AND/OR A NUMBER</b>  for each answer.</p><p class=\"\"><b>Fearnley Sports Center </b></p><p class=\"\"><b> Lifeguard Application Form</b></p><p class=\"\"><u><b>Personal details</b></u></p><p class=\"\"><b>Name</b>:                                             Peter Smith</p><p><b>Home address</b>:                              130 South Main Street, Lake  <span class=\"qnum\">1</span><input class=\"gap\" data-q=\"1\" aria-label=\"Câu 1\" autocomplete=\"off\" spellcheck=\"false\"></p><p><b>Contact number</b>:                          <span class=\"qnum\">2</span><input class=\"gap\" data-q=\"2\" aria-label=\"Câu 2\" autocomplete=\"off\" spellcheck=\"false\"> (cell phone)</p><p class=\"\"><b>Present occupation</b>:</p><p>has temporary job as a part-time <span class=\"qnum\">3</span><input class=\"gap\" data-q=\"3\" aria-label=\"Câu 3\" autocomplete=\"off\" spellcheck=\"false\"></p><p class=\"\">is studying PE</p><p>wants to be a high school <span class=\"qnum\">4</span><input class=\"gap\" data-q=\"4\" aria-label=\"Câu 4\" autocomplete=\"off\" spellcheck=\"false\"> coach</p><p class=\"\"><u><b>Qualifications</b></u></p><p class=\"\"><b>Already holds:</b>                               water safety certificate</p><p><b>Certificate expires in</b> :                  <span class=\"qnum\">5</span><input class=\"gap\" data-q=\"5\" aria-label=\"Câu 5\" autocomplete=\"off\" spellcheck=\"false\"></p><p class=\"\"><u><b>Relevant work experience </b></u></p><p><b>Lifeguard at</b>:                                  the  <span class=\"qnum\">6</span><input class=\"gap\" data-q=\"6\" aria-label=\"Câu 6\" autocomplete=\"off\" spellcheck=\"false\">  in Fearnley</p><p><b>Additional relevant skills</b>:             <span class=\"qnum\">7</span><input class=\"gap\" data-q=\"7\" aria-label=\"Câu 7\" autocomplete=\"off\" spellcheck=\"false\"></p><p class=\"\"><b>Other Information</b>:                       is happy to</p><p>work on   <span class=\"qnum\">8</span><input class=\"gap\" data-q=\"8\" aria-label=\"Câu 8\" autocomplete=\"off\" spellcheck=\"false\"> mornings</p><p>start at <span class=\"qnum\">9</span><input class=\"gap\" data-q=\"9\" aria-label=\"Câu 9\" autocomplete=\"off\" spellcheck=\"false\"> o’clock</p><p><b>How did the applicant find out about this Job</b>?  on the <span class=\"qnum\">10</span><input class=\"gap\" data-q=\"10\" aria-label=\"Câu 10\" autocomplete=\"off\" spellcheck=\"false\"></p>"}, {"number": 2, "html": "<p class=\"subheading\"><b>Questions 11–16</b></p><p class=\"instruction\">Choose the correct answer.</p><p class=\"\"><b>Becoming a millionaire</b></p><div data-render-choice=\"11\"></div><div data-render-choice=\"12\"></div><div data-render-choice=\"13\"></div><div data-render-choice=\"14\"></div><div data-render-choice=\"15\"></div><div data-render-choice=\"16\"></div>\n<p class=\"subheading\"><b>Questions 17–18</b></p><p class=\"instruction\">Choose TWO correct answers.</p><div data-render-pair=\"17\"></div>\n<p class=\"subheading\"><b>Questions 19–20</b></p><p class=\"instruction\">Choose TWO correct answers.</p><div data-render-pair=\"19\"></div>"}, {"number": 3, "html": "<p class=\"subheading\"><b>Questions 21–26</b></p><p class=\"instruction\">Choose the correct answer.</p><p class=\"\"><b> Feedback on second year of Performance Arts Course</b></p><div data-render-choice=\"21\"></div><div data-render-choice=\"22\"></div><div data-render-choice=\"23\"></div><div data-render-choice=\"24\"></div><div data-render-choice=\"25\"></div><div data-render-choice=\"26\"></div>\n<p class=\"subheading\"><b>Questions 27–30</b></p><p class=\"instruction\"><i><b>What do the students say about each of the following types of careers in performance arts?</b></i></p><p class=\"instruction\">Choose FOUR correct answers, <b>A-F</b>, next to questions 27-30.</p><p class=\"instruction\"><b>Comments</b></p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> The pay can be low.</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> There is a lot of competition.</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> An additional qualification is required</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> Good communication skills are required</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> People with experience feel very positive about it.</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> It is a relatively unpopular choice.</button></div><p class=\"matching-row\" data-drop=\"27\"><span class=\"qnum\">27</span>Performance <select class=\"answer-select\" data-q=\"27\" aria-label=\"Câu 27\"><option value=\"\">Chọn</option><option value=\"A\">A · The pay can be low.</option><option value=\"B\">B · There is a lot of competition.</option><option value=\"C\">C · An additional qualification is required</option><option value=\"D\">D · Good communication skills are required</option><option value=\"E\">E · People with experience feel very positive about it.</option><option value=\"F\">F · It is a relatively unpopular choice.</option></select></p><p class=\"matching-row\" data-drop=\"28\"><span class=\"qnum\">28</span>Education <select class=\"answer-select\" data-q=\"28\" aria-label=\"Câu 28\"><option value=\"\">Chọn</option><option value=\"A\">A · The pay can be low.</option><option value=\"B\">B · There is a lot of competition.</option><option value=\"C\">C · An additional qualification is required</option><option value=\"D\">D · Good communication skills are required</option><option value=\"E\">E · People with experience feel very positive about it.</option><option value=\"F\">F · It is a relatively unpopular choice.</option></select></p><p class=\"matching-row\" data-drop=\"29\"><span class=\"qnum\">29</span>Theatre management <select class=\"answer-select\" data-q=\"29\" aria-label=\"Câu 29\"><option value=\"\">Chọn</option><option value=\"A\">A · The pay can be low.</option><option value=\"B\">B · There is a lot of competition.</option><option value=\"C\">C · An additional qualification is required</option><option value=\"D\">D · Good communication skills are required</option><option value=\"E\">E · People with experience feel very positive about it.</option><option value=\"F\">F · It is a relatively unpopular choice.</option></select></p><p class=\"matching-row\" data-drop=\"30\"><span class=\"qnum\">30</span>Marketing <select class=\"answer-select\" data-q=\"30\" aria-label=\"Câu 30\"><option value=\"\">Chọn</option><option value=\"A\">A · The pay can be low.</option><option value=\"B\">B · There is a lot of competition.</option><option value=\"C\">C · An additional qualification is required</option><option value=\"D\">D · Good communication skills are required</option><option value=\"E\">E · People with experience feel very positive about it.</option><option value=\"F\">F · It is a relatively unpopular choice.</option></select></p>"}, {"number": 4, "html": "<p class=\"subheading\"><b>Questions 31–40</b></p><p class=\"instruction\">Complete the notes below.</p><p class=\"instruction\">Write ONE WORD ONLY for each answer.</p><p class=\"\"><b>Sea lion tracking study (Western Australia)</b></p><p class=\"\"><b>Reason for the study</b></p><p class=\"\">The Australian sea lion is an endangered species</p><p class=\"\">Until 1892, numbers were affected by hunting</p><p>Sea lions are now affected by nets used to control <span class=\"qnum\">31</span><input class=\"gap\" data-q=\"31\" aria-label=\"Câu 31\" autocomplete=\"off\" spellcheck=\"false\"></p><p class=\"\"><b>Animal tracking systems</b></p><p>Considerations when choosing a tracking method include  <span class=\"qnum\">32</span><input class=\"gap\" data-q=\"32\" aria-label=\"Câu 32\" autocomplete=\"off\" spellcheck=\"false\"> and ease of use.</p><p>Plastic tags: the animal must be easy to  <span class=\"qnum\">33</span><input class=\"gap\" data-q=\"33\" aria-label=\"Câu 33\" autocomplete=\"off\" spellcheck=\"false\"></p><p>GPS tracking will not work in the  <span class=\"qnum\">34</span><input class=\"gap\" data-q=\"34\" aria-label=\"Câu 34\" autocomplete=\"off\" spellcheck=\"false\"></p><p>In isolated regions, some animals are tracked by  <span class=\"qnum\">35</span><input class=\"gap\" data-q=\"35\" aria-label=\"Câu 35\" autocomplete=\"off\" spellcheck=\"false\"> (e.g.  the polar bear)</p><p class=\"\">Some animals are identified by markings (e. g.  the dolphin is identified by its scars).</p><p class=\"\"><b>Challenges of tracking sea lions</b></p><p>Perth study: the sea lions lost their tags. (They rubbed against <span class=\"qnum\">36</span><input class=\"gap\" data-q=\"36\" aria-label=\"Câu 36\" autocomplete=\"off\" spellcheck=\"false\"> to remove them).</p><p>Californian researchers used  <span class=\"qnum\">37</span><input class=\"gap\" data-q=\"37\" aria-label=\"Câu 37\" autocomplete=\"off\" spellcheck=\"false\"> to identify sea lions. (This was unreliable due to regular loss of fur).</p><p class=\"\"><b>Our study</b></p><p class=\"\"><b>Aims:</b></p><p class=\"\">i)      to find out if sea lions&#x27; whiskers can be used to identify them</p><p>ii)   to create a <span class=\"qnum\">38</span><input class=\"gap\" data-q=\"38\" aria-label=\"Câu 38\" autocomplete=\"off\" spellcheck=\"false\"> to use as a guide</p><p class=\"\"><b>Methods:</b></p><p>i)         contacting  <span class=\"qnum\">39</span><input class=\"gap\" data-q=\"39\" aria-label=\"Câu 39\" autocomplete=\"off\" spellcheck=\"false\"> in Australia for photographs</p><p>ii)        asking the  <span class=\"qnum\">40</span><input class=\"gap\" data-q=\"40\" aria-label=\"Câu 40\" autocomplete=\"off\" spellcheck=\"false\"> to get involved</p>"}], "passages": [], "singles": [{"n": 11, "prompt": "Arthur feels that when starting a business, mistakes should be", "options": ["seen as an opportunity to learn.", "predicted and minimised.", "avoided at all costs"]}, {"n": 12, "prompt": "Recent American studies found that confidence will", "options": ["sometimes reduce people's chances of success.", "be increased by reading self-help books.", "ensure good results on business courses."]}, {"n": 13, "prompt": "The American studies recommended that new entrepreneurs", "options": ["listen to their colleagues' advice.", "get professional help when things go wrong.", "remain concentrated on their aims."]}, {"n": 14, "prompt": "What does Arthur say about his own experience of marketing?", "options": ["He relied on what he already knew.", "He hired an expert to take care of it.", "He realised its importance too late."]}, {"n": 15, "prompt": "What does Arthur think Is an important quality shared by good leaders?", "options": ["They are ambitious for their company.", "They can deal with difficult people.", "They earn the respect of their workforce."]}, {"n": 16, "prompt": "What does Arthur say about taking risks?", "options": ["He advises being cautions.", "He favours a long-term view.", "He believes it is financially advantageous."]}, {"n": 21, "prompt": "Gina chose to study performance arts at this university because the course", "options": ["has a very good reputation.", "has links with various theatres.", "has an international flavour."]}, {"n": 22, "prompt": "Which of the options they chose have Gina and Charlie both found useful?", "options": ["Movement Analysis", "Dance and Drama", "The Body in Dance"]}, {"n": 23, "prompt": "What did Charlie do during his work experience?", "options": ["He worked in a costume department.", "He performed with a ballet company.", "He helped out at a dance school for children."]}, {"n": 24, "prompt": "What does Gina say she learnt from her work experience?", "options": ["how to organise her time better", "how to work better in a team", "how to cope when under pressure"]}, {"n": 25, "prompt": "What does Charlie say about his dissertation topic?", "options": ["He wanted it to be different from those of other students.", "He had already done an assignment in this area.", "He was inspired to choose it by a performance he saw."]}, {"n": 26, "prompt": "Which aspect of writing a dissertation is Gina worried about?", "options": ["finding enough to say", "doing the background reading", "presenting it in an appropriate way"]}], "pairs": [{"n": 17, "size": 2, "prompt": "Which TWO things does Arthur say people should focus on when developing their business idea?", "options": ["making sure the idea is original", "offering a better deal than competitors", "being committed to it", "paying attention to detail", "fixing realistic prices"]}, {"n": 19, "size": 2, "prompt": "Which TWO things does Arthur say helped him get his business started?", "options": ["family support", "getting a loan from a bank", "good business advice", "a favourable economic climate", "an effective approach to business"]}], "answers": {"1": ["Elsinore"], "2": ["077896245"], "3": ["waiter"], "4": ["baseball"], "5": ["October"], "6": ["beach"], "7": ["diving"], "8": ["Saturday"], "9": ["six", "6"], "10": ["radio"], "11": ["A"], "12": ["A"], "13": ["C"], "14": ["B"], "15": ["C"], "16": ["A"], "17": ["B/C"], "18": ["B/C"], "19": ["A/E"], "20": ["A/E"], "21": ["B"], "22": ["A"], "23": ["A"], "24": ["B"], "25": ["C"], "26": ["B"], "27": ["E"], "28": ["C"], "29": ["A"], "30": ["F"], "31": ["sharks"], "32": ["cost"], "33": ["catch"], "34": ["ocean"], "35": ["helicopter"], "36": ["rocks"], "37": ["paint"], "38": ["diagram"], "39": ["zoos"], "40": ["public"]}, "explanations": {}, "transcriptSegments": {"1": [{"id": "s1-t1", "text": "You will hear a number of different recordings, and you will have to answer questions on what you hear. There will be time for you to read the instructions and questions, and you will have a chance to check your work. All the recordings will be played once only.", "html": "<p>You will hear a number of different recordings, and you will have to answer questions on what you hear. There will be time for you to read the instructions and questions, and you will have a chance to check your work. All the recordings will be played once only.</p>", "start": null}, {"id": "s1-t2", "text": "The test is in four parts. Write all your answers in the listening question booklet. At the end of the test, you will be given ten minutes to transfer your answers to an answer sheet.", "html": "<p>The test is in four parts. Write all your answers in the listening question booklet. At the end of the test, you will be given ten minutes to transfer your answers to an answer sheet.</p>", "start": null}, {"id": "s1-t3", "text": "Now turn to part one on page two of your question booklet. Part One You will hear a man called Peter phoning a sports centre manager about a job. First, you have some time to look at questions one to four.", "html": "<p>Now turn to part one on page two of your question booklet. Part One You will hear a man called Peter phoning a sports centre manager about a job. First, you have some time to look at questions one to four.</p>", "start": null}, {"id": "s1-t4", "text": "Now listen carefully and answer questions one to four. Hello, Fernley Sports Centre. How can I help you? Yes, I'd like to apply for one of the lifeguard jobs you advertised this week.", "html": "<p>Now listen carefully and answer questions one to four. Hello, Fernley Sports Centre. How can I help you? Yes, I&#x27;d like to apply for one of the lifeguard jobs you advertised this week.</p>", "start": null}, {"id": "s1-t5", "text": "Right, we can do that now over the phone. I'll just need some information from you. Let me get a form.", "html": "<p>Right, we can do that now over the phone. I&#x27;ll just need some information from you. Let me get a form.</p>", "start": null}, {"id": "s1-t6", "text": "Okay, so let's start with your name. Peter Smith Okay, can you let me have your home address? It's 130 South Main Street, Lake Elsinore. Okay, I'm new around here.", "html": "<p>Okay, so let&#x27;s start with your name. Peter Smith Okay, can you let me have your home address? It&#x27;s 130 South Main Street, Lake Elsinore. Okay, I&#x27;m new around here.</p>", "start": null}, {"id": "s1-t7", "text": "Can you spell that for me? Yes, it's E-L-S-I-N-O-R-E. Okay, got that. And your phone number? My home number's 9-5-1-6-7-4-3-1-2-4, but it's best to ring me on my cell phone.", "html": "<p>Can you spell that for me? Yes, it&#x27;s E-L-S-I-N-O-R-E. Okay, got that. And your phone number? My home number&#x27;s 9-5-1-6-7-4-3-1-2-4, but it&#x27;s best to ring me on my cell phone.</p>", "start": null}, {"id": "s1-t8", "text": "That's 0-7-7-8-9-6-2-4-5. Okay, now what do you do? Are you still in college or are you working full time? I'm in my second year here at Fernley, and this vacation I've got a job as a part-time waiter. Okay, I guess if you're at Fernley College you'll be studying physical education? They all seem to do that there.", "html": "<p>That&#x27;s 0-7-7-8-9-6-2-4-5. Okay, now what do you do? Are you still in college or are you working full time? I&#x27;m in my second year here at Fernley, and this vacation I&#x27;ve got a job as a part-time waiter. Okay, I guess if you&#x27;re at Fernley College you&#x27;ll be studying physical education? They all seem to do that there.</p>", "start": null}, {"id": "s1-t9", "text": "That's right. Then I hope to go on and coach baseball in high school, something like that. I guess it all depends on how I do in my final exams.", "html": "<p>That&#x27;s right. Then I hope to go on and coach baseball in high school, something like that. I guess it all depends on how I do in my final exams.</p>", "start": null}, {"id": "s1-t10", "text": "Okay, sounds good to me. Before you hear the rest of the conversation, you have some time to look at questions 5 to 10. Now listen and answer questions 5 to 10.", "html": "<p>Okay, sounds good to me. Before you hear the rest of the conversation, you have some time to look at questions 5 to 10. Now listen and answer questions 5 to 10.</p>", "start": null}, {"id": "s1-t11", "text": "Now, the next part of the form deals with qualifications. Do you have the water safety certificate? We absolutely insist on that. Yes, I do.", "html": "<p>Now, the next part of the form deals with qualifications. Do you have the water safety certificate? We absolutely insist on that. Yes, I do.</p>", "start": null}, {"id": "s1-t12", "text": "So how long will it last before you have to do a refresher course? I took it last November, so it'll run out in October. Okay, good. Now, what about work experience as a lifeguard? Well, I've had about four months' experience.", "html": "<p>So how long will it last before you have to do a refresher course? I took it last November, so it&#x27;ll run out in October. Okay, good. Now, what about work experience as a lifeguard? Well, I&#x27;ve had about four months&#x27; experience.</p>", "start": null}, {"id": "s1-t13", "text": "Which swimming pool was that at? I need to have details of your employer, obviously, so we can get a reference. Oh, it was at the beach here in Fernley. I can get the number of the person you need to contact.", "html": "<p>Which swimming pool was that at? I need to have details of your employer, obviously, so we can get a reference. Oh, it was at the beach here in Fernley. I can get the number of the person you need to contact.</p>", "start": null}, {"id": "s1-t14", "text": "Good. And do you have any other additional skills I can put down? You can put down diving. I've done that for a long time now.", "html": "<p>Good. And do you have any other additional skills I can put down? You can put down diving. I&#x27;ve done that for a long time now.</p>", "start": null}, {"id": "s1-t15", "text": "I'm also keen on rock climbing, but that's not really relevant here. No. Okay.", "html": "<p>I&#x27;m also keen on rock climbing, but that&#x27;s not really relevant here. No. Okay.</p>", "start": null}, {"id": "s1-t16", "text": "And I need to ask when you would prefer to work. You can choose either Saturday mornings or any time Monday to Friday. We've got enough people on Sundays at the moment.", "html": "<p>And I need to ask when you would prefer to work. You can choose either Saturday mornings or any time Monday to Friday. We&#x27;ve got enough people on Sundays at the moment.</p>", "start": null}, {"id": "s1-t17", "text": "Well, not Monday to Friday, because I'm at the restaurant weekday evenings. Okay. We open at six.", "html": "<p>Well, not Monday to Friday, because I&#x27;m at the restaurant weekday evenings. Okay. We open at six.</p>", "start": null}, {"id": "s1-t18", "text": "Could you start that early? No, that's fine. I prefer that to working late. Okay.", "html": "<p>Could you start that early? No, that&#x27;s fine. I prefer that to working late. Okay.</p>", "start": null}, {"id": "s1-t19", "text": "Now I need to speak to the committee who run the sports centre here, but you should hear back from us pretty soon, and then they'll probably arrange an interview. Thanks very much. Great.", "html": "<p>Now I need to speak to the committee who run the sports centre here, but you should hear back from us pretty soon, and then they&#x27;ll probably arrange an interview. Thanks very much. Great.</p>", "start": null}, {"id": "s1-t20", "text": "Now, before you go, I'd just like to ask you how you found out about our advertisement. We always ask this. Was it from the newspaper or the radio? I heard the advertisement this morning when I was driving into college.", "html": "<p>Now, before you go, I&#x27;d just like to ask you how you found out about our advertisement. We always ask this. Was it from the newspaper or the radio? I heard the advertisement this morning when I was driving into college.</p>", "start": null}, {"id": "s1-t21", "text": "I don't usually read the local paper. All right. Thanks.", "html": "<p>I don&#x27;t usually read the local paper. All right. Thanks.</p>", "start": null}, {"id": "s1-t22", "text": "Well, that's all. Hope to see you soon. That is the end of part one.", "html": "<p>Well, that&#x27;s all. Hope to see you soon. That is the end of part one.</p>", "start": null}, {"id": "s1-t23", "text": "You now have one minute to check your answers to part one.", "html": "<p>You now have one minute to check your answers to part one.</p>", "start": null}], "2": [{"id": "s2-t1", "text": "Part two. You will hear part of a radio programme in which a successful businessman is advising listeners on how to become a self-made millionaire.", "html": "<p>Part two. You will hear part of a radio programme in which a successful businessman is advising listeners on how to become a self-made millionaire.</p>", "start": null}, {"id": "s2-t2", "text": "First, you have some time to look at questions 11 to 16. Now listen carefully and answer questions 11 to 16. Everybody dreams of becoming a millionaire one day.", "html": "<p>First, you have some time to look at questions 11 to 16. Now listen carefully and answer questions 11 to 16. Everybody dreams of becoming a millionaire one day.</p>", "start": null}, {"id": "s2-t3", "text": "So, we asked Arthur Knowles, who made his millions in the plumbing business, to give the budding entrepreneurs among you a few tips on how to make your first million. Arthur, welcome to the programme. Thanks, Sue.", "html": "<p>So, we asked Arthur Knowles, who made his millions in the plumbing business, to give the budding entrepreneurs among you a few tips on how to make your first million. Arthur, welcome to the programme. Thanks, Sue.</p>", "start": null}, {"id": "s2-t4", "text": "So, Arthur, what advice do you have for our listeners? Well, one thing I've heard people say is that when you're starting up a business, you can't afford to make mistakes. Well, I believe in the old saying, a person who never made a mistake never made anything. You can't really predict when you'll make mistakes and you have to look at them as a positive experience and one that means you won't make the same mistake again.", "html": "<p>So, Arthur, what advice do you have for our listeners? Well, one thing I&#x27;ve heard people say is that when you&#x27;re starting up a business, you can&#x27;t afford to make mistakes. Well, I believe in the old saying, a person who never made a mistake never made anything. You can&#x27;t really predict when you&#x27;ll make mistakes and you have to look at them as a positive experience and one that means you won&#x27;t make the same mistake again.</p>", "start": null}, {"id": "s2-t5", "text": "You need to be able to cope with the world of business. But according to recent American business school studies, believing in yourself isn't enough by itself to guarantee success. Confidence can be a good thing, but a person can have too much confidence.", "html": "<p>You need to be able to cope with the world of business. But according to recent American business school studies, believing in yourself isn&#x27;t enough by itself to guarantee success. Confidence can be a good thing, but a person can have too much confidence.</p>", "start": null}, {"id": "s2-t6", "text": "And people who try to learn to be confident by buying those how-to-succeed books are just wasting their time. The advice given in these American studies was that being a successful entrepreneur comes down to having the right attitude. It's no good getting depressed every time something goes wrong.", "html": "<p>And people who try to learn to be confident by buying those how-to-succeed books are just wasting their time. The advice given in these American studies was that being a successful entrepreneur comes down to having the right attitude. It&#x27;s no good getting depressed every time something goes wrong.</p>", "start": null}, {"id": "s2-t7", "text": "Always keep your goals in mind and never give up. And don't listen to all the people around you who say, oh, this will never work. One thing I've learned in business is that you don't have to be an expert in everything.", "html": "<p>Always keep your goals in mind and never give up. And don&#x27;t listen to all the people around you who say, oh, this will never work. One thing I&#x27;ve learned in business is that you don&#x27;t have to be an expert in everything.</p>", "start": null}, {"id": "s2-t8", "text": "Marketing, for example. When I started my business, I tried to do it all myself. But I soon realised that although I knew everything there was to know about plumbing, I didn't have much idea about how to sell my ideas.", "html": "<p>Marketing, for example. When I started my business, I tried to do it all myself. But I soon realised that although I knew everything there was to know about plumbing, I didn&#x27;t have much idea about how to sell my ideas.</p>", "start": null}, {"id": "s2-t9", "text": "So, I got someone who knew more about this to take care of the marketing side of things for me. And as for leadership, well, you've got to be someone your workers look up to because you've been seen to make the right decisions. You have to be able to control people, but listen to them at the same time.", "html": "<p>So, I got someone who knew more about this to take care of the marketing side of things for me. And as for leadership, well, you&#x27;ve got to be someone your workers look up to because you&#x27;ve been seen to make the right decisions. You have to be able to control people, but listen to them at the same time.</p>", "start": null}, {"id": "s2-t10", "text": "Some people are driven to make their companies successful, but that too often leads to a ruthless approach. Then there's the question of taking risks, even calculated ones. I personally feel it's actually better to tread carefully when it comes to taking short-term risks.", "html": "<p>Some people are driven to make their companies successful, but that too often leads to a ruthless approach. Then there&#x27;s the question of taking risks, even calculated ones. I personally feel it&#x27;s actually better to tread carefully when it comes to taking short-term risks.</p>", "start": null}, {"id": "s2-t11", "text": "You need a degree of vision, certainly, but it's easy to get carried away by your desire to increase profits. And if things go wrong, you can end up losing more than you gain. Before you hear the rest of the programme, you have some time to look at questions 17 to 20.", "html": "<p>You need a degree of vision, certainly, but it&#x27;s easy to get carried away by your desire to increase profits. And if things go wrong, you can end up losing more than you gain. Before you hear the rest of the programme, you have some time to look at questions 17 to 20.</p>", "start": null}, {"id": "s2-t12", "text": "Now listen and answer questions 17 to 20. So, if you have a great idea for a business, what should you do next? Well, the first thing to ask yourself is whether there's a need for your product or service. Can you cater for people's needs better than existing companies? You don't need to worry about whether it's original or not because there isn't always enough of a demand for completely new ideas.", "html": "<p>Now listen and answer questions 17 to 20. So, if you have a great idea for a business, what should you do next? Well, the first thing to ask yourself is whether there&#x27;s a need for your product or service. Can you cater for people&#x27;s needs better than existing companies? You don&#x27;t need to worry about whether it&#x27;s original or not because there isn&#x27;t always enough of a demand for completely new ideas.</p>", "start": null}, {"id": "s2-t13", "text": "And the second thing to ask yourself is not what colour should the packet be or how much should it cost, but do I care enough about this idea to dedicate the next 10 years of my life to it? Because realistically, that's how long it will take. Tell us how you got started, Arthur. How do you explain your early success? Well, I started my business just as the economy was going into a recession, which wasn't the best time and I was lucky to survive, especially as the banks weren't being particularly supportive to small businesses at that time.", "html": "<p>And the second thing to ask yourself is not what colour should the packet be or how much should it cost, but do I care enough about this idea to dedicate the next 10 years of my life to it? Because realistically, that&#x27;s how long it will take. Tell us how you got started, Arthur. How do you explain your early success? Well, I started my business just as the economy was going into a recession, which wasn&#x27;t the best time and I was lucky to survive, especially as the banks weren&#x27;t being particularly supportive to small businesses at that time.</p>", "start": null}, {"id": "s2-t14", "text": "If I'd listened to the business advice I was given back then, I'd never have got started. My strengths were that I knew I could provide a better service than my competitors, who really hadn't spotted the opportunities that were out there, and that my wife had a good job and was able to pay the household bills while I was getting the company on its feet. The first couple of years were very tough, but I knew I would make it eventually.", "html": "<p>If I&#x27;d listened to the business advice I was given back then, I&#x27;d never have got started. My strengths were that I knew I could provide a better service than my competitors, who really hadn&#x27;t spotted the opportunities that were out there, and that my wife had a good job and was able to pay the household bills while I was getting the company on its feet. The first couple of years were very tough, but I knew I would make it eventually.</p>", "start": null}, {"id": "s2-t15", "text": "OK, now we're going to take some calls from listeners. That is the end of Part 2. You now have 30 seconds to check your answers to Part 2.", "html": "<p>OK, now we&#x27;re going to take some calls from listeners. That is the end of Part 2. You now have 30 seconds to check your answers to Part 2.</p>", "start": null}], "3": [{"id": "s3-t1", "text": "Part 3 You will hear two students of performance arts called Charlie and Gina preparing to give feedback at the end of the second year of their three-year course. First, you have some time to look at questions 21 to 26.", "html": "<p>Part 3 You will hear two students of performance arts called Charlie and Gina preparing to give feedback at the end of the second year of their three-year course. First, you have some time to look at questions 21 to 26.</p>", "start": null}, {"id": "s3-t2", "text": "Now listen carefully and answer questions 21 to 26. So, Gina, we've got to give our tutor some feedback on how we feel about the course now we've come to the end of our second year. Is it OK with you if we have a chat together before we go and see him? Sure, Charlie.", "html": "<p>Now listen carefully and answer questions 21 to 26. So, Gina, we&#x27;ve got to give our tutor some feedback on how we feel about the course now we&#x27;ve come to the end of our second year. Is it OK with you if we have a chat together before we go and see him? Sure, Charlie.</p>", "start": null}, {"id": "s3-t3", "text": "So did you choose this university to do performance arts because it's got such a good reputation? That's what hooked me in. Well, there are other good places which I also considered, but when I looked into things further, I was impressed by the connections this course has with a whole range of theatres of different types. So, even though I was tempted to go and study abroad, I decided to come here in the end.", "html": "<p>So did you choose this university to do performance arts because it&#x27;s got such a good reputation? That&#x27;s what hooked me in. Well, there are other good places which I also considered, but when I looked into things further, I was impressed by the connections this course has with a whole range of theatres of different types. So, even though I was tempted to go and study abroad, I decided to come here in the end.</p>", "start": null}, {"id": "s3-t4", "text": "And you don't regret it? No, it's been brilliant, especially the options this year. The body and dance option I did for this term has been particularly stimulating. I'm sorry I didn't go for that one too, but I did dance and drama, which was brilliant too.", "html": "<p>And you don&#x27;t regret it? No, it&#x27;s been brilliant, especially the options this year. The body and dance option I did for this term has been particularly stimulating. I&#x27;m sorry I didn&#x27;t go for that one too, but I did dance and drama, which was brilliant too.</p>", "start": null}, {"id": "s3-t5", "text": "I think the most valuable option I've done was the movement analysis course we did in the first year. Absolutely. It's provided a great foundation for all our other work since then.", "html": "<p>I think the most valuable option I&#x27;ve done was the movement analysis course we did in the first year. Absolutely. It&#x27;s provided a great foundation for all our other work since then.</p>", "start": null}, {"id": "s3-t6", "text": "So let's talk about our work experience last summer. You went to Finland, didn't you? That's right. I was at their National Ballet Theatre.", "html": "<p>So let&#x27;s talk about our work experience last summer. You went to Finland, didn&#x27;t you? That&#x27;s right. I was at their National Ballet Theatre.</p>", "start": null}, {"id": "s3-t7", "text": "I didn't get the chance to go on stage, but I helped out with sewing clothes for current productions and even with designing some for future shows. It was brilliant. I got to know a lot of students studying at the local dance school, and I may get the chance to go back there next summer.", "html": "<p>I didn&#x27;t get the chance to go on stage, but I helped out with sewing clothes for current productions and even with designing some for future shows. It was brilliant. I got to know a lot of students studying at the local dance school, and I may get the chance to go back there next summer.</p>", "start": null}, {"id": "s3-t8", "text": "Hmm. I've been offered more work at the place where I was working in Canada. Great.", "html": "<p>Hmm. I&#x27;ve been offered more work at the place where I was working in Canada. Great.</p>", "start": null}, {"id": "s3-t9", "text": "So what do you think you gained most from the experience? I think I've got much better at controlling my stress levels. For me, it was probably the fact that I learned a lot about collaborating with others rather than working independently. I was lucky to be able to do that in a situation that wasn't too stressful.", "html": "<p>So what do you think you gained most from the experience? I think I&#x27;ve got much better at controlling my stress levels. For me, it was probably the fact that I learned a lot about collaborating with others rather than working independently. I was lucky to be able to do that in a situation that wasn&#x27;t too stressful.</p>", "start": null}, {"id": "s3-t10", "text": "Also, I had to organise my time well, but I've always been reasonably good at that. That's good. So we've got quite a few things ready to say to our tutor.", "html": "<p>Also, I had to organise my time well, but I&#x27;ve always been reasonably good at that. That&#x27;s good. So we&#x27;ve got quite a few things ready to say to our tutor.</p>", "start": null}, {"id": "s3-t11", "text": "It'd be a good chance to ask him any questions we have too, of course. I also think it could be helpful to discuss our future plans. For example, what we're planning to do our dissertations on.", "html": "<p>It&#x27;d be a good chance to ask him any questions we have too, of course. I also think it could be helpful to discuss our future plans. For example, what we&#x27;re planning to do our dissertations on.</p>", "start": null}, {"id": "s3-t12", "text": "Sure. I was unsure about whether to focus on globalisation in dance or on stage design. I did an essay on globalisation in my first year and really enjoyed it.", "html": "<p>Sure. I was unsure about whether to focus on globalisation in dance or on stage design. I did an essay on globalisation in my first year and really enjoyed it.</p>", "start": null}, {"id": "s3-t13", "text": "But then I saw a spectacular production at the Royal Opera House, and that settled me on stage design. I know another student who's planning to work on that too, so we can discuss things together a bit. OK.", "html": "<p>But then I saw a spectacular production at the Royal Opera House, and that settled me on stage design. I know another student who&#x27;s planning to work on that too, so we can discuss things together a bit. OK.</p>", "start": null}, {"id": "s3-t14", "text": "That could be useful. I'm planning to do something on current trends in contemporary dance for my dissertation. That sounds pretty challenging.", "html": "<p>That could be useful. I&#x27;m planning to do something on current trends in contemporary dance for my dissertation. That sounds pretty challenging.</p>", "start": null}, {"id": "s3-t15", "text": "It's a big topic. It might not be easy to organise in a coherent way. I've thought about it quite a lot, and I think that'll be OK.", "html": "<p>It&#x27;s a big topic. It might not be easy to organise in a coherent way. I&#x27;ve thought about it quite a lot, and I think that&#x27;ll be OK.</p>", "start": null}, {"id": "s3-t16", "text": "And I feel confident about how to write a longer piece of work. I'm in a bit of a panic, though, about how I'll get through all the literature. There seems to be so much.", "html": "<p>And I feel confident about how to write a longer piece of work. I&#x27;m in a bit of a panic, though, about how I&#x27;ll get through all the literature. There seems to be so much.</p>", "start": null}, {"id": "s3-t17", "text": "Hopefully it won't all be relevant. Quite. Before you hear the rest of the discussion, you have some time to look at questions 27 to 30.", "html": "<p>Hopefully it won&#x27;t all be relevant. Quite. Before you hear the rest of the discussion, you have some time to look at questions 27 to 30.</p>", "start": null}, {"id": "s3-t18", "text": "Now listen and answer questions 27 to 30. So, have you made any career plans yet? I'm still undecided. I've thought about performance, of course.", "html": "<p>Now listen and answer questions 27 to 30. So, have you made any career plans yet? I&#x27;m still undecided. I&#x27;ve thought about performance, of course.</p>", "start": null}, {"id": "s3-t19", "text": "Yes, I think lots of graduates from here take that route. But it's a hard life, involving lots of tough, repetitive practise, as well as actually appearing on stage. Yes, but the performance I've met know that's essential for the job and say they wouldn't change what they do for the world.", "html": "<p>Yes, I think lots of graduates from here take that route. But it&#x27;s a hard life, involving lots of tough, repetitive practise, as well as actually appearing on stage. Yes, but the performance I&#x27;ve met know that&#x27;s essential for the job and say they wouldn&#x27;t change what they do for the world.</p>", "start": null}, {"id": "s3-t20", "text": "I know lots of graduates go into education, teaching at various levels, but that means doing some kind of post-grad certificate. But I think it would be interesting, rewarding work. I was wondering about theatre management as a possible option.", "html": "<p>I know lots of graduates go into education, teaching at various levels, but that means doing some kind of post-grad certificate. But I think it would be interesting, rewarding work. I was wondering about theatre management as a possible option.</p>", "start": null}, {"id": "s3-t21", "text": "That's what our tutor did before he got into teaching, isn't it? Yes, but he said he quickly realised it wasn't for him. He wasn't earning enough to live on. I can imagine his communication skills are better than his business skills as well.", "html": "<p>That&#x27;s what our tutor did before he got into teaching, isn&#x27;t it? Yes, but he said he quickly realised it wasn&#x27;t for him. He wasn&#x27;t earning enough to live on. I can imagine his communication skills are better than his business skills as well.</p>", "start": null}, {"id": "s3-t22", "text": "Marketing's a possibility, of course. Sure. I've read something saying it can be an interesting career, though I don't think many graduates go for this.", "html": "<p>Marketing&#x27;s a possibility, of course. Sure. I&#x27;ve read something saying it can be an interesting career, though I don&#x27;t think many graduates go for this.</p>", "start": null}, {"id": "s3-t23", "text": "But that might mean there's not so much competition, as in many other fields of dance. Right. So, now shall we make a list? That is the end of part three.", "html": "<p>But that might mean there&#x27;s not so much competition, as in many other fields of dance. Right. So, now shall we make a list? That is the end of part three.</p>", "start": null}, {"id": "s3-t24", "text": "You now have 30 seconds to check your answers to part three.", "html": "<p>You now have 30 seconds to check your answers to part three.</p>", "start": null}], "4": [{"id": "s4-t1", "text": "Part Four You will hear part of a presentation to biology students on new research into sea lions. First you have some time to look at questions 31 to 40.", "html": "<p>Part Four You will hear part of a presentation to biology students on new research into sea lions. First you have some time to look at questions 31 to 40.</p>", "start": null}, {"id": "s4-t2", "text": "Now listen carefully and answer questions 31 to 40. Hello everybody. I'm here today to tell you about a new research study that my team here at the university is doing on the sea lions that live along the coast of Western Australia.", "html": "<p>Now listen carefully and answer questions 31 to 40. Hello everybody. I&#x27;m here today to tell you about a new research study that my team here at the university is doing on the sea lions that live along the coast of Western Australia.</p>", "start": null}, {"id": "s4-t3", "text": "You may be wondering why we've been studying this animal. Well, Australian sea lions have been identified as an endangered species, so there's a real need to count them and find out just how many there are. Up until 1892, the population of these animals was severely depleted because of hunting.", "html": "<p>You may be wondering why we&#x27;ve been studying this animal. Well, Australian sea lions have been identified as an endangered species, so there&#x27;s a real need to count them and find out just how many there are. Up until 1892, the population of these animals was severely depleted because of hunting.</p>", "start": null}, {"id": "s4-t4", "text": "That's no longer allowed. But today there is a new danger. Sea lions often forage for food in the same areas along the coastlines where there are nets used to catch sharks.", "html": "<p>That&#x27;s no longer allowed. But today there is a new danger. Sea lions often forage for food in the same areas along the coastlines where there are nets used to catch sharks.</p>", "start": null}, {"id": "s4-t5", "text": "Unfortunately, they tend to get caught up in the nets by accident and drown. Now, we wanted to monitor the population of sea lions in this area, but we weren't sure of the best way to do it. There are several different animal tracking methods, which vary in their effectiveness, and there are different factors to consider.", "html": "<p>Unfortunately, they tend to get caught up in the nets by accident and drown. Now, we wanted to monitor the population of sea lions in this area, but we weren&#x27;t sure of the best way to do it. There are several different animal tracking methods, which vary in their effectiveness, and there are different factors to consider.</p>", "start": null}, {"id": "s4-t6", "text": "One of the most important of these is the cost, but you also have to consider how easy your chosen method is to use. You may choose a traditional method, like a plastic tag. They're relatively straightforward to attach, but they're really only suitable to use with animals that you can catch quite easily.", "html": "<p>One of the most important of these is the cost, but you also have to consider how easy your chosen method is to use. You may choose a traditional method, like a plastic tag. They&#x27;re relatively straightforward to attach, but they&#x27;re really only suitable to use with animals that you can catch quite easily.</p>", "start": null}, {"id": "s4-t7", "text": "You might also go with a more modern method like GPS tracking, which uses satellite technology to transmit data on the animal around the clock. One drawback for marine animals, though, is that they don't transmit a signal in the ocean. You only get data when they're on land.", "html": "<p>You might also go with a more modern method like GPS tracking, which uses satellite technology to transmit data on the animal around the clock. One drawback for marine animals, though, is that they don&#x27;t transmit a signal in the ocean. You only get data when they&#x27;re on land.</p>", "start": null}, {"id": "s4-t8", "text": "There are certain large animals in remote areas that have to be tracked using a helicopter. The polar bear is a good example. Now, an important part of tracking is being able to clearly identify the animal.", "html": "<p>There are certain large animals in remote areas that have to be tracked using a helicopter. The polar bear is a good example. Now, an important part of tracking is being able to clearly identify the animal.</p>", "start": null}, {"id": "s4-t9", "text": "Some, like zebras, are identified by markings such as their stripes. While the dolphin usually has distinguishing scars on its body that can help tell them apart. Sea lions don't have any markings like this, which is just one of the challenges of tracking them.", "html": "<p>Some, like zebras, are identified by markings such as their stripes. While the dolphin usually has distinguishing scars on its body that can help tell them apart. Sea lions don&#x27;t have any markings like this, which is just one of the challenges of tracking them.</p>", "start": null}, {"id": "s4-t10", "text": "When researchers in Perth tried to use electronic tags in a sea lion study, they found that the sea lions had removed their tracking devices by deliberately rubbing up against rocks. This was something the researchers hadn't anticipated. Researchers in California studying American sea lions tried a different method.", "html": "<p>When researchers in Perth tried to use electronic tags in a sea lion study, they found that the sea lions had removed their tracking devices by deliberately rubbing up against rocks. This was something the researchers hadn&#x27;t anticipated. Researchers in California studying American sea lions tried a different method.</p>", "start": null}, {"id": "s4-t11", "text": "They applied paint to the animals. They thought this would be a better, less invasive means of identification. Unfortunately, this didn't work so well either, because sea lions moult every year and shed their fur along with the identifying mark.", "html": "<p>They applied paint to the animals. They thought this would be a better, less invasive means of identification. Unfortunately, this didn&#x27;t work so well either, because sea lions moult every year and shed their fur along with the identifying mark.</p>", "start": null}, {"id": "s4-t12", "text": "So let's look at our current study. We have several aims that we'd like to achieve. The first of these is to try to establish whether sea lions can be identified from the whiskers on their face.", "html": "<p>So let&#x27;s look at our current study. We have several aims that we&#x27;d like to achieve. The first of these is to try to establish whether sea lions can be identified from the whiskers on their face.</p>", "start": null}, {"id": "s4-t13", "text": "These are much coarser than a cat's whiskers, so easier to see. Our theory is that the pattern of these whiskers may be as individual as a fingerprint on a human. If this is in fact true, then we think this could be an effective way to identify them.", "html": "<p>These are much coarser than a cat&#x27;s whiskers, so easier to see. Our theory is that the pattern of these whiskers may be as individual as a fingerprint on a human. If this is in fact true, then we think this could be an effective way to identify them.</p>", "start": null}, {"id": "s4-t14", "text": "Our second aim is to come up with a diagram of sea lion whisker patterns, so this can be used as a guide for us and other studies. We're using a few different methods to help us do all this. We know that we need to build up a wide range of visual data.", "html": "<p>Our second aim is to come up with a diagram of sea lion whisker patterns, so this can be used as a guide for us and other studies. We&#x27;re using a few different methods to help us do all this. We know that we need to build up a wide range of visual data.</p>", "start": null}, {"id": "s4-t15", "text": "So firstly, we've been in touch with zoos around Australia to gather photographs from them of the faces of any sea lions they have. This won't be enough to achieve our purpose though, so we're also broadening our search by inviting the public to take part in our research. We're hoping this will result in hundreds of useful images we can use.", "html": "<p>So firstly, we&#x27;ve been in touch with zoos around Australia to gather photographs from them of the faces of any sea lions they have. This won&#x27;t be enough to achieve our purpose though, so we&#x27;re also broadening our search by inviting the public to take part in our research. We&#x27;re hoping this will result in hundreds of useful images we can use.</p>", "start": null}, {"id": "s4-t16", "text": "That is the end of part four. You now have one minute to check your answers to part four. That is the end of the listening test.", "html": "<p>That is the end of part four. You now have one minute to check your answers to part four. That is the end of the listening test.</p>", "start": null}, {"id": "s4-t17", "text": "You now have 10 minutes to transfer your answers to the listening answer sheet.", "html": "<p>You now have 10 minutes to transfer your answers to the listening answer sheet.</p>", "start": null}]}, "transcripts": {"1": "<p>You will hear a number of different recordings, and you will have to answer questions on what you hear. There will be time for you to read the instructions and questions, and you will have a chance to check your work. All the recordings will be played once only.</p><p>The test is in four parts. Write all your answers in the listening question booklet. At the end of the test, you will be given ten minutes to transfer your answers to an answer sheet.</p><p>Now turn to part one on page two of your question booklet. Part One You will hear a man called Peter phoning a sports centre manager about a job. First, you have some time to look at questions one to four.</p><p>Now listen carefully and answer questions one to four. Hello, Fernley Sports Centre. How can I help you? Yes, I&#x27;d like to apply for one of the lifeguard jobs you advertised this week.</p><p>Right, we can do that now over the phone. I&#x27;ll just need some information from you. Let me get a form.</p><p>Okay, so let&#x27;s start with your name. Peter Smith Okay, can you let me have your home address? It&#x27;s 130 South Main Street, Lake Elsinore. Okay, I&#x27;m new around here.</p><p>Can you spell that for me? Yes, it&#x27;s E-L-S-I-N-O-R-E. Okay, got that. And your phone number? My home number&#x27;s 9-5-1-6-7-4-3-1-2-4, but it&#x27;s best to ring me on my cell phone.</p><p>That&#x27;s 0-7-7-8-9-6-2-4-5. Okay, now what do you do? Are you still in college or are you working full time? I&#x27;m in my second year here at Fernley, and this vacation I&#x27;ve got a job as a part-time waiter. Okay, I guess if you&#x27;re at Fernley College you&#x27;ll be studying physical education? They all seem to do that there.</p><p>That&#x27;s right. Then I hope to go on and coach baseball in high school, something like that. I guess it all depends on how I do in my final exams.</p><p>Okay, sounds good to me. Before you hear the rest of the conversation, you have some time to look at questions 5 to 10. Now listen and answer questions 5 to 10.</p><p>Now, the next part of the form deals with qualifications. Do you have the water safety certificate? We absolutely insist on that. Yes, I do.</p><p>So how long will it last before you have to do a refresher course? I took it last November, so it&#x27;ll run out in October. Okay, good. Now, what about work experience as a lifeguard? Well, I&#x27;ve had about four months&#x27; experience.</p><p>Which swimming pool was that at? I need to have details of your employer, obviously, so we can get a reference. Oh, it was at the beach here in Fernley. I can get the number of the person you need to contact.</p><p>Good. And do you have any other additional skills I can put down? You can put down diving. I&#x27;ve done that for a long time now.</p><p>I&#x27;m also keen on rock climbing, but that&#x27;s not really relevant here. No. Okay.</p><p>And I need to ask when you would prefer to work. You can choose either Saturday mornings or any time Monday to Friday. We&#x27;ve got enough people on Sundays at the moment.</p><p>Well, not Monday to Friday, because I&#x27;m at the restaurant weekday evenings. Okay. We open at six.</p><p>Could you start that early? No, that&#x27;s fine. I prefer that to working late. Okay.</p><p>Now I need to speak to the committee who run the sports centre here, but you should hear back from us pretty soon, and then they&#x27;ll probably arrange an interview. Thanks very much. Great.</p><p>Now, before you go, I&#x27;d just like to ask you how you found out about our advertisement. We always ask this. Was it from the newspaper or the radio? I heard the advertisement this morning when I was driving into college.</p><p>I don&#x27;t usually read the local paper. All right. Thanks.</p><p>Well, that&#x27;s all. Hope to see you soon. That is the end of part one.</p><p>You now have one minute to check your answers to part one.</p>", "2": "<p>Part two. You will hear part of a radio programme in which a successful businessman is advising listeners on how to become a self-made millionaire.</p><p>First, you have some time to look at questions 11 to 16. Now listen carefully and answer questions 11 to 16. Everybody dreams of becoming a millionaire one day.</p><p>So, we asked Arthur Knowles, who made his millions in the plumbing business, to give the budding entrepreneurs among you a few tips on how to make your first million. Arthur, welcome to the programme. Thanks, Sue.</p><p>So, Arthur, what advice do you have for our listeners? Well, one thing I&#x27;ve heard people say is that when you&#x27;re starting up a business, you can&#x27;t afford to make mistakes. Well, I believe in the old saying, a person who never made a mistake never made anything. You can&#x27;t really predict when you&#x27;ll make mistakes and you have to look at them as a positive experience and one that means you won&#x27;t make the same mistake again.</p><p>You need to be able to cope with the world of business. But according to recent American business school studies, believing in yourself isn&#x27;t enough by itself to guarantee success. Confidence can be a good thing, but a person can have too much confidence.</p><p>And people who try to learn to be confident by buying those how-to-succeed books are just wasting their time. The advice given in these American studies was that being a successful entrepreneur comes down to having the right attitude. It&#x27;s no good getting depressed every time something goes wrong.</p><p>Always keep your goals in mind and never give up. And don&#x27;t listen to all the people around you who say, oh, this will never work. One thing I&#x27;ve learned in business is that you don&#x27;t have to be an expert in everything.</p><p>Marketing, for example. When I started my business, I tried to do it all myself. But I soon realised that although I knew everything there was to know about plumbing, I didn&#x27;t have much idea about how to sell my ideas.</p><p>So, I got someone who knew more about this to take care of the marketing side of things for me. And as for leadership, well, you&#x27;ve got to be someone your workers look up to because you&#x27;ve been seen to make the right decisions. You have to be able to control people, but listen to them at the same time.</p><p>Some people are driven to make their companies successful, but that too often leads to a ruthless approach. Then there&#x27;s the question of taking risks, even calculated ones. I personally feel it&#x27;s actually better to tread carefully when it comes to taking short-term risks.</p><p>You need a degree of vision, certainly, but it&#x27;s easy to get carried away by your desire to increase profits. And if things go wrong, you can end up losing more than you gain. Before you hear the rest of the programme, you have some time to look at questions 17 to 20.</p><p>Now listen and answer questions 17 to 20. So, if you have a great idea for a business, what should you do next? Well, the first thing to ask yourself is whether there&#x27;s a need for your product or service. Can you cater for people&#x27;s needs better than existing companies? You don&#x27;t need to worry about whether it&#x27;s original or not because there isn&#x27;t always enough of a demand for completely new ideas.</p><p>And the second thing to ask yourself is not what colour should the packet be or how much should it cost, but do I care enough about this idea to dedicate the next 10 years of my life to it? Because realistically, that&#x27;s how long it will take. Tell us how you got started, Arthur. How do you explain your early success? Well, I started my business just as the economy was going into a recession, which wasn&#x27;t the best time and I was lucky to survive, especially as the banks weren&#x27;t being particularly supportive to small businesses at that time.</p><p>If I&#x27;d listened to the business advice I was given back then, I&#x27;d never have got started. My strengths were that I knew I could provide a better service than my competitors, who really hadn&#x27;t spotted the opportunities that were out there, and that my wife had a good job and was able to pay the household bills while I was getting the company on its feet. The first couple of years were very tough, but I knew I would make it eventually.</p><p>OK, now we&#x27;re going to take some calls from listeners. That is the end of Part 2. You now have 30 seconds to check your answers to Part 2.</p>", "3": "<p>Part 3 You will hear two students of performance arts called Charlie and Gina preparing to give feedback at the end of the second year of their three-year course. First, you have some time to look at questions 21 to 26.</p><p>Now listen carefully and answer questions 21 to 26. So, Gina, we&#x27;ve got to give our tutor some feedback on how we feel about the course now we&#x27;ve come to the end of our second year. Is it OK with you if we have a chat together before we go and see him? Sure, Charlie.</p><p>So did you choose this university to do performance arts because it&#x27;s got such a good reputation? That&#x27;s what hooked me in. Well, there are other good places which I also considered, but when I looked into things further, I was impressed by the connections this course has with a whole range of theatres of different types. So, even though I was tempted to go and study abroad, I decided to come here in the end.</p><p>And you don&#x27;t regret it? No, it&#x27;s been brilliant, especially the options this year. The body and dance option I did for this term has been particularly stimulating. I&#x27;m sorry I didn&#x27;t go for that one too, but I did dance and drama, which was brilliant too.</p><p>I think the most valuable option I&#x27;ve done was the movement analysis course we did in the first year. Absolutely. It&#x27;s provided a great foundation for all our other work since then.</p><p>So let&#x27;s talk about our work experience last summer. You went to Finland, didn&#x27;t you? That&#x27;s right. I was at their National Ballet Theatre.</p><p>I didn&#x27;t get the chance to go on stage, but I helped out with sewing clothes for current productions and even with designing some for future shows. It was brilliant. I got to know a lot of students studying at the local dance school, and I may get the chance to go back there next summer.</p><p>Hmm. I&#x27;ve been offered more work at the place where I was working in Canada. Great.</p><p>So what do you think you gained most from the experience? I think I&#x27;ve got much better at controlling my stress levels. For me, it was probably the fact that I learned a lot about collaborating with others rather than working independently. I was lucky to be able to do that in a situation that wasn&#x27;t too stressful.</p><p>Also, I had to organise my time well, but I&#x27;ve always been reasonably good at that. That&#x27;s good. So we&#x27;ve got quite a few things ready to say to our tutor.</p><p>It&#x27;d be a good chance to ask him any questions we have too, of course. I also think it could be helpful to discuss our future plans. For example, what we&#x27;re planning to do our dissertations on.</p><p>Sure. I was unsure about whether to focus on globalisation in dance or on stage design. I did an essay on globalisation in my first year and really enjoyed it.</p><p>But then I saw a spectacular production at the Royal Opera House, and that settled me on stage design. I know another student who&#x27;s planning to work on that too, so we can discuss things together a bit. OK.</p><p>That could be useful. I&#x27;m planning to do something on current trends in contemporary dance for my dissertation. That sounds pretty challenging.</p><p>It&#x27;s a big topic. It might not be easy to organise in a coherent way. I&#x27;ve thought about it quite a lot, and I think that&#x27;ll be OK.</p><p>And I feel confident about how to write a longer piece of work. I&#x27;m in a bit of a panic, though, about how I&#x27;ll get through all the literature. There seems to be so much.</p><p>Hopefully it won&#x27;t all be relevant. Quite. Before you hear the rest of the discussion, you have some time to look at questions 27 to 30.</p><p>Now listen and answer questions 27 to 30. So, have you made any career plans yet? I&#x27;m still undecided. I&#x27;ve thought about performance, of course.</p><p>Yes, I think lots of graduates from here take that route. But it&#x27;s a hard life, involving lots of tough, repetitive practise, as well as actually appearing on stage. Yes, but the performance I&#x27;ve met know that&#x27;s essential for the job and say they wouldn&#x27;t change what they do for the world.</p><p>I know lots of graduates go into education, teaching at various levels, but that means doing some kind of post-grad certificate. But I think it would be interesting, rewarding work. I was wondering about theatre management as a possible option.</p><p>That&#x27;s what our tutor did before he got into teaching, isn&#x27;t it? Yes, but he said he quickly realised it wasn&#x27;t for him. He wasn&#x27;t earning enough to live on. I can imagine his communication skills are better than his business skills as well.</p><p>Marketing&#x27;s a possibility, of course. Sure. I&#x27;ve read something saying it can be an interesting career, though I don&#x27;t think many graduates go for this.</p><p>But that might mean there&#x27;s not so much competition, as in many other fields of dance. Right. So, now shall we make a list? That is the end of part three.</p><p>You now have 30 seconds to check your answers to part three.</p>", "4": "<p>Part Four You will hear part of a presentation to biology students on new research into sea lions. First you have some time to look at questions 31 to 40.</p><p>Now listen carefully and answer questions 31 to 40. Hello everybody. I&#x27;m here today to tell you about a new research study that my team here at the university is doing on the sea lions that live along the coast of Western Australia.</p><p>You may be wondering why we&#x27;ve been studying this animal. Well, Australian sea lions have been identified as an endangered species, so there&#x27;s a real need to count them and find out just how many there are. Up until 1892, the population of these animals was severely depleted because of hunting.</p><p>That&#x27;s no longer allowed. But today there is a new danger. Sea lions often forage for food in the same areas along the coastlines where there are nets used to catch sharks.</p><p>Unfortunately, they tend to get caught up in the nets by accident and drown. Now, we wanted to monitor the population of sea lions in this area, but we weren&#x27;t sure of the best way to do it. There are several different animal tracking methods, which vary in their effectiveness, and there are different factors to consider.</p><p>One of the most important of these is the cost, but you also have to consider how easy your chosen method is to use. You may choose a traditional method, like a plastic tag. They&#x27;re relatively straightforward to attach, but they&#x27;re really only suitable to use with animals that you can catch quite easily.</p><p>You might also go with a more modern method like GPS tracking, which uses satellite technology to transmit data on the animal around the clock. One drawback for marine animals, though, is that they don&#x27;t transmit a signal in the ocean. You only get data when they&#x27;re on land.</p><p>There are certain large animals in remote areas that have to be tracked using a helicopter. The polar bear is a good example. Now, an important part of tracking is being able to clearly identify the animal.</p><p>Some, like zebras, are identified by markings such as their stripes. While the dolphin usually has distinguishing scars on its body that can help tell them apart. Sea lions don&#x27;t have any markings like this, which is just one of the challenges of tracking them.</p><p>When researchers in Perth tried to use electronic tags in a sea lion study, they found that the sea lions had removed their tracking devices by deliberately rubbing up against rocks. This was something the researchers hadn&#x27;t anticipated. Researchers in California studying American sea lions tried a different method.</p><p>They applied paint to the animals. They thought this would be a better, less invasive means of identification. Unfortunately, this didn&#x27;t work so well either, because sea lions moult every year and shed their fur along with the identifying mark.</p><p>So let&#x27;s look at our current study. We have several aims that we&#x27;d like to achieve. The first of these is to try to establish whether sea lions can be identified from the whiskers on their face.</p><p>These are much coarser than a cat&#x27;s whiskers, so easier to see. Our theory is that the pattern of these whiskers may be as individual as a fingerprint on a human. If this is in fact true, then we think this could be an effective way to identify them.</p><p>Our second aim is to come up with a diagram of sea lion whisker patterns, so this can be used as a guide for us and other studies. We&#x27;re using a few different methods to help us do all this. We know that we need to build up a wide range of visual data.</p><p>So firstly, we&#x27;ve been in touch with zoos around Australia to gather photographs from them of the faces of any sea lions they have. This won&#x27;t be enough to achieve our purpose though, so we&#x27;re also broadening our search by inviting the public to take part in our research. We&#x27;re hoping this will result in hundreds of useful images we can use.</p><p>That is the end of part four. You now have one minute to check your answers to part four. That is the end of the listening test.</p><p>You now have 10 minutes to transfer your answers to the listening answer sheet.</p>"}, "questionSegments": {"1": ["s1-t6"], "2": ["s1-t8"], "3": ["s1-t8"], "4": ["s1-t9"], "5": ["s1-t12"], "6": ["s1-t13"], "7": ["s1-t14"], "8": ["s1-t16"], "9": ["s1-t17"], "10": ["s1-t20"], "11": ["s2-t4"], "12": ["s2-t5"], "13": ["s2-t7"], "14": ["s2-t9"], "15": ["s2-t9"], "16": ["s2-t10"], "17": ["s2-t12"], "18": ["s2-t13"], "19": ["s2-t14"], "20": ["s2-t14"], "21": ["s3-t3"], "22": ["s3-t5"], "23": ["s3-t7"], "24": ["s3-t9"], "25": ["s3-t13"], "26": ["s3-t16"], "27": ["s3-t19"], "28": ["s3-t20"], "29": ["s3-t21"], "30": ["s3-t22"], "31": ["s4-t4"], "32": ["s4-t6"], "33": ["s4-t6"], "34": ["s4-t7"], "35": ["s4-t8"], "36": ["s4-t10"], "37": ["s4-t11"], "38": ["s4-t14"], "39": ["s4-t15"], "40": ["s4-t15"]}, "evidenceCues": {"2": "That's 0-7-7-8-9-6-2-4-5", "11": "look at them as a positive experience", "12": "a person can have too much confidence", "13": "Always keep your goals in mind", "14": "I got someone who knew more about this", "15": "someone your workers look up to", "16": "better to tread carefully", "17": "Can you cater for people's needs better", "18": "do I care enough about this idea", "19": "I could provide a better service than my competitors", "20": "my wife had a good job", "21": "impressed by the connections this course has", "22": "most valuable option I've done was the movement analysis", "23": "helped out with sewing clothes", "24": "learned a lot about collaborating with others", "25": "spectacular production at the Royal Opera House", "26": "how I'll get through all the literature", "27": "wouldn't change what they do for the world", "28": "post-grad certificate", "29": "He wasn't earning enough to live on", "30": "I don't think many graduates go for this", "33": "animals that you can catch quite easily"}, "headingsBySection": {}, "grading": {"pairs": [17, 19], "sets": [{"n": 17, "size": 2}, {"n": 19, "size": 2}]}, "groups": [[1, 10], [11, 20], [21, 30], [31, 40]], "questionTypes": {"1": "gap", "2": "gap", "3": "gap", "4": "gap", "5": "gap", "6": "gap", "7": "gap", "8": "gap", "9": "gap", "10": "gap", "11": "single", "12": "single", "13": "single", "14": "single", "15": "single", "16": "single", "17": "multi", "18": "multi", "19": "multi", "20": "multi", "21": "single", "22": "single", "23": "single", "24": "single", "25": "single", "26": "single", "27": "matching", "28": "matching", "29": "matching", "30": "matching", "31": "gap", "32": "gap", "33": "gap", "34": "gap", "35": "gap", "36": "gap", "37": "gap", "38": "gap", "39": "gap", "40": "gap"}, "audioFiles": {"1": "2-1.mp3", "2": "2-2.mp3", "3": "2-3.mp3", "4": "2-4.mp3"}, "audio": {"1": "Listening - Vol 8/Test 2/audio/part-1.mp3", "2": "Listening - Vol 8/Test 2/audio/part-2.mp3", "3": "Listening - Vol 8/Test 2/audio/part-3.mp3", "4": "Listening - Vol 8/Test 2/audio/part-4.mp3"}, "sourceAnswerKey": {"1": ["Elsinore"], "2": ["077896245"], "3": ["waiter"], "4": ["baseball"], "5": ["October"], "6": ["beach"], "7": ["diving"], "8": ["Saturday"], "9": ["six", "6"], "10": ["radio"], "11": ["A"], "12": ["A"], "13": ["C"], "14": ["B"], "15": ["C"], "16": ["A"], "17": ["B/C"], "18": ["B/C"], "19": ["A/E"], "20": ["A/E"], "21": ["B"], "22": ["A"], "23": ["A"], "24": ["B"], "25": ["C"], "26": ["B"], "27": ["E"], "28": ["C"], "29": ["A"], "30": ["F"], "31": ["sharks"], "32": ["cost"], "33": ["catch"], "34": ["ocean"], "35": ["helicopter"], "36": ["rocks"], "37": ["paint"], "38": ["diagram"], "39": ["zoos"], "40": ["public"]}, "sourceNotes": [], "hasAnswerKey": true};
